INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2014H2_GK', 'RK_SA_ARCH_2014H2_GK_Q024', '商业智能是企业对商业数据的搜集、管理和分析的系统过程，主要技术包括（24）。', 24, '单选题', '[{"key":"A","text":"数据仓库、联机分析和数据挖掘","scores":{"score":1}},{"key":"B","text":"数据采集、数据清洗和数据挖掘","scores":{"score":0}},{"key":"C","text":"联机分析、多维度分析和跨维度分析","scores":{"score":0}},{"key":"D","text":"数据仓库、数据挖掘和业务优化重组","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":24,"correctOptionKey":"A","explanation":"本题考查商业智能的基础知识。\\n商业智能通常被理解为将组织中现有的数据转化为知识，帮助组织做出明智的业务经营决策。商业智能的实现涉及到软件、硬件、咨询服务及应用，是对商业信息的搜集、管理和分析过程，目的是使企业的各级决策者获得知识或洞察力，促使他们做出对企业更有利的决策。商业智能一般由数据仓库、联机分析处理、数据挖掘、数据备份和恢复等部分组成。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

